import { Effect, FileSystem, Path } from "effect"

export interface AnnouncementOptions {
  readonly version: string
  readonly releaseUrl: string
  readonly templateDirectory?: string
}

export interface Announcement {
  readonly subject: string
  readonly body: string
}

export const buildReleaseAnnouncement = (options: AnnouncementOptions) =>
  Effect.gen(function*() {
    const fs = yield* FileSystem.FileSystem
    const path = yield* Path.Path
    const directory = options.templateDirectory ??
      path.join(path.resolve(), "assets", "notifications")
    const templatePath = path.join(directory, "release.md")
    const template = yield* fs.readFileString(templatePath)

    const body = template
      .replaceAll("{{version}}", options.version)
      .replaceAll("{{releaseUrl}}", options.releaseUrl)
      .trim()

    return {
      subject: `Version ${options.version} is available`,
      body
    } satisfies Announcement
  })
